{
  "businessAnalysisParagraphs": [
    "吴起县中小企业融资担保有限责任公司作为县区级政府性融资担保机构，本年度综合评价结果为良好。机构在担保放大倍数方面表现突出，实际完成 3.48 倍，远超目标值；但在新增担保业务规模及再担保规模方面完成进度滞后，实际完成额与目标值存在较大差距。整体业务结构中小微三农融资担保业务占比及分险业务占比均达到目标要求，合作业务代偿率控制在目标范围内，风险总体可控。"
  ],
  "annualTargetLead": "本年度政策目标完成情况显示，机构在部分结构性指标上表现优异，但规模类指标完成度较低。",
  "annualTargetAnalysisParagraphs": [
    "新增担保业务规模目标 15.00 亿元，实际完成 0.47 亿元，完成率 3.13%；再担保规模目标 12.00 亿元，实际完成 0.45 亿元，完成率 3.75%，规模类指标完成显著不足。小微三农融资担保业务占比目标 0.80%，实际 1.06%，完成率 132.50%；分险业务占比目标 0.99%，实际 1.06%，完成率 107.07%，结构性指标完成情况良好。担保放大倍数目标 2.03 倍，实际 3.48 倍，完成率 171.43%，资金使用效率较高。风险指标方面，合作业务代偿率实际 0.05%，未超过 20.00% 的目标上限；代偿补偿返还率目标 0.10%，实际 0.00%，完成率 0.00%。"
  ],
  "creditUsageParagraphs": [
    "机构本年度业务开展主要集中在存量业务的维持与风险管控，新增业务拓展力度有待加强。在代偿补偿返还方面，实际返还率为 0.00%，需关注后续代偿追偿及补偿机制的落实情况。业务开展过程中，担保放大倍数达到 3.48 倍，显示资本金运用效率较高，但需结合业务规模不足的情况综合考量业务可持续性。"
  ],
  "conclusionParagraphs": [
    "综上所述，吴起县中小企业融资担保有限责任公司本年度综合评价等级为良好。建议机构下一步重点加大业务拓展力度，提升新增担保业务规模及再担保业务规模，确保政策目标有效落地；同时继续保持较低代偿率的优势，优化代偿补偿返还机制，推动业务规模与质量协调发展。"
  ]
}
